#!/usr/bin/env bash
# Maintains the ui-screenshots branch. It always holds exactly one orphan commit, force-pushed,
# so replaced or pruned images drop out of history instead of piling up.
#
#   ui-screenshots.sh main  <dir>     README images rendered from main      -> main/
#   ui-screenshots.sh pr    <run-id>  PR screenshots from a CI run artifact -> pr-N/<sha>/ + PR comment
#   ui-screenshots.sh prune <days>    drop pr-N/ folders for PRs closed more than <days> ago
#
# Needs GH_TOKEN (contents: write; pull-requests: write for "pr") and GH_REPO=owner/name.
set -euo pipefail

BRANCH=ui-screenshots
RAW="https://raw.githubusercontent.com/$GH_REPO/$BRANCH"
MARK='<!-- ui-screenshots -->'
url="https://x-access-token:$GH_TOKEN@github.com/$GH_REPO.git"
tree=$(mktemp -d)

if git ls-remote --exit-code --heads "$url" "$BRANCH" >/dev/null 2>&1; then
  git clone -q --depth 1 --branch "$BRANCH" "$url" "$tree"
else
  git init -q -b "$BRANCH" "$tree" && git -C "$tree" remote add origin "$url"
fi

# Copy only plainly named PNGs; artifacts from fork PRs are untrusted.
copy_pngs() {
  mkdir -p "$2"
  for f in "$1"/*.png; do
    [ -f "$f" ] || continue
    n=$(basename "$f")
    [[ $n =~ ^[a-z0-9-]+\.png$ ]] && cp "$f" "$2/$n"
  done
  return 0
}

publish() {
  cat > "$tree/README.md" <<'EOF'
# UI screenshots

Generated by `.github/workflows/ui-screenshots.yml` from `src/tests/ui`. Don't commit here: the branch
is force-pushed as a single commit on every update.

- `main/`: README images, rendered from `main`
- `pr-N/<sha>/`: screenshots posted on pull request N, pruned a week after it closes
EOF
  cd "$tree"
  git add -A
  if git rev-parse -q --verify HEAD >/dev/null && git diff --cached --quiet HEAD; then
    echo "ui-screenshots unchanged"; return 0
  fi
  git -c user.name="github-actions[bot]" -c user.email="41898282+github-actions[bot]@users.noreply.github.com" \
    commit -q -m "$1"
  # Re-root as one parentless commit so history never grows.
  git branch -q -f flat "$(git -c user.name="github-actions[bot]" \
    -c user.email="41898282+github-actions[bot]@users.noreply.github.com" commit-tree "HEAD^{tree}" -m "$1")"
  git push -q -f origin flat:"$BRANCH"
  echo "pushed $BRANCH: $1"
}

comment() {
  local n=$1 dir=$2 sha=$3 body id name cells="" i=0
  for f in "$tree/$dir"/*.png; do
    name=$(basename "$f" .png)
    cells+="<td valign=\"top\"><b>$name</b><br><a href=\"$RAW/$dir/$name.png\"><img src=\"$RAW/$dir/$name.png\" width=\"420\"></a></td>"
    i=$((i + 1))
    if (( i % 2 == 0 )); then cells+="</tr><tr>"; fi
  done
  body="$MARK
### UI screenshots

Rendered at \`$sha\` from mocked API data by \`src/tests/ui/screenshots.py\`. Updated on every push; click to enlarge.

<table><tr>$cells</tr></table>"
  id=$(gh api "repos/$GH_REPO/issues/$n/comments" --paginate \
    --jq ".[] | select(.user.login == \"github-actions[bot]\" and (.body | startswith(\"$MARK\"))) | .id" | head -n1)
  if [ -n "$id" ]; then
    gh api -X PATCH "repos/$GH_REPO/issues/comments/$id" -f body="$body" >/dev/null
  else
    gh api "repos/$GH_REPO/issues/$n/comments" -f body="$body" >/dev/null
  fi
  echo "commented on #$n"
}

case "${1:-}" in
  main)
    rm -rf "$tree/main"
    copy_pngs "$2" "$tree/main"
    publish "README screenshots from ${GITHUB_SHA:-local}"
    ;;
  pr)
    run=$2 shots=$(mktemp -d)
    if ! gh run download "$run" -R "$GH_REPO" -n ui-screenshots -D "$shots" 2>/dev/null; then
      echo "no UI screenshots in run $run (UI unchanged)"; exit 0
    fi
    n=$(jq -r '.pr' "$shots/pr.json"); sha=$(jq -r '.sha' "$shots/pr.json")
    [[ $n =~ ^[0-9]+$ && $sha =~ ^[0-9a-f]{40}$ ]] || { echo "bad pr.json"; exit 1; }
    # The artifact names its PR; only trust it if that PR's head is the commit CI ran on.
    if [ "$sha" != "${HEAD_SHA:?}" ] || [ "$(gh pr view "$n" -R "$GH_REPO" --json headRefOid -q .headRefOid)" != "$HEAD_SHA" ]; then
      echo "artifact does not match PR #$n head (stale or spoofed); skipping"; exit 0
    fi
    dir="pr-$n/${sha:0:7}"
    rm -rf "${tree:?}/pr-$n"
    copy_pngs "$shots" "$tree/$dir"
    ( publish "PR #$n at ${sha:0:7}" )
    comment "$n" "$dir" "${sha:0:7}"
    ;;
  prune)
    cutoff=$(date -u -d "-${2:-7} days" +%s)
    for d in "$tree"/pr-*/; do
      [ -d "$d" ] || continue
      n=$(basename "$d"); n=${n#pr-}
      info=$(gh pr view "$n" -R "$GH_REPO" --json state,closedAt -q '.state + " " + (.closedAt // "")') || continue
      read -r state closed <<<"$info"
      if [ "$state" != OPEN ] && [ -n "$closed" ] && [ "$(date -u -d "$closed" +%s)" -lt "$cutoff" ]; then
        rm -rf "$d"; echo "pruned pr-$n ($state $closed)"
      fi
    done
    publish "Prune closed PRs"
    ;;
  *) echo "usage: $0 main <dir> | pr <run-id> | prune [days]" >&2; exit 2 ;;
esac
